using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<ClubDb>(
    o => o.UseInMemoryDatabase("clubs"));
var app = builder.Build();

// The clubs the Grove starts with.
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider
        .GetRequiredService<ClubDb>();
    db.Clubs.AddRange(
        new Club { Name = "Owl Watchers", Meets = "Monday" },
        new Club { Name = "Frog Choir", Meets = "Wednesday" },
        new Club { Name = "Acorn Artists", Meets = "Friday" });
    db.SaveChanges();
}

// Every club, A to Z.
app.MapGet("/api/clubs", (ClubDb db) =>
    db.Clubs.OrderBy(c => c.Name).ToList());

app.Run();

