using Microsoft.EntityFrameworkCore;

public class Team
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Division { get; set; } = "";
}

public class Match
{
    public int Id { get; set; }
    public int HomeTeamId { get; set; }
    public int AwayTeamId { get; set; }
    public int HomeGoals { get; set; }
    public int AwayGoals { get; set; }
}

// One row of the standings table.
public record Standing(string Team, int Played, int Points);

public class LeagueDb(DbContextOptions<LeagueDb> options)
    : DbContext(options)
{
    public DbSet<Team> Teams => Set<Team>();
    public DbSet<Match> Matches => Set<Match>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<Team>().HasData(
            T(1, "Riverton Otters", "north"),
            T(2, "Hilltop Hawks", "north"),
            T(3, "Lakeside Lynx", "south"),
            T(4, "Meadow Mice", "south"),
            T(5, "Canyon Comets", "south"));
        model.Entity<Match>().HasData(
            M(1, 1, 2, 1, 2),
            M(2, 3, 4, 2, 2),
            M(3, 2, 3, 3, 0),
            M(4, 4, 1, 0, 1),
            M(5, 1, 3, 2, 2),
            M(6, 2, 4, 1, 1));
    }

    static Team T(int id, string name, string division) =>
        new() { Id = id, Name = name, Division = division };

    static Match M(int id, int home, int away, int hg, int ag) =>
        new()
        {
            Id = id, HomeTeamId = home, AwayTeamId = away,
            HomeGoals = hg, AwayGoals = ag,
        };
}

